/******************************************************************************
 * Function Name   : failNative
 * Description     : Report a deterministic codec error without modifying caller results.
 * Input Parameters: error, message
 * Return Value    : False
 * Date            : 2026.11.09
 ******************************************************************************/
bool failNative(QString *error, const QString &message) //20261109-0 add
{
    if (error != nullptr)
    {
        *error = message;
    }
    return false;
}

/******************************************************************************
 * Function Name   : parseUnsignedComponent
 * Description     : Parse all ASCII digits with an explicit radix and checked accumulation.
 * Input Parameters: text, radix, value
 * Return Value    : True after a complete nonnegative u32 conversion.
 * Date            : 2026.11.09
 ******************************************************************************/
bool parseUnsignedComponent(const QString &text, int radix, u32 *value) //20261109-0 add
{
    quint64 accumulated;
    ushort code;
    int digit;
    int index;

    if (text.isEmpty())
    {
        return false;
    }
    accumulated = 0;
    for (index = 0; index < text.size(); ++index)
    {
        code = text[index].unicode();
        if (code >= '0' && code <= '9')
        {
            digit = code - '0';
        }
        else if (code >= 'a' && code <= 'f')
        {
            digit = code - 'a' + 10;
        }
        else if (code >= 'A' && code <= 'F')
        {
            digit = code - 'A' + 10;
        }
        else
        {
            return false;
        }
        if (digit >= radix)
        {
            return false;
        }
        accumulated = accumulated * static_cast<quint64>(radix) + static_cast<quint64>(digit);
        if (accumulated > std::numeric_limits<u32>::max())
        {
            return false;
        }
    }
    *value = static_cast<u32>(accumulated);
    return true;
}

/******************************************************************************
 * Function Name   : parseCoordinates
 * Description     : Preserve each observed delimiter, packed suffix and LG string-length semantic.
 * Input Parameters: rule, text, coordinates
 * Return Value    : True after all components satisfy the strict lexical grammar.
 * Date            : 2026.11.09
 ******************************************************************************/
bool parseCoordinates(const PlcNativeFamilyRule &rule, const QString &text,
                      std::array<u32, 3> *coordinates) //20261109-0 add
{
    QStringList parts;
    QString normalized;
    u32 packed;
    int index;
    int radix;

    if (text.isEmpty() || text.size() > 31)
    {
        return false;
    }
    *coordinates = {};
    if (rule.grammar == PlcNativeGrammar::PackedDecimalBit)
    {
        if (!parseUnsignedComponent(text, 10, &packed))
        {
            return false;
        }
        (*coordinates)[0] = packed / 100;
        (*coordinates)[1] = packed % 100;
        return true;
    }
    if (rule.grammar == PlcNativeGrammar::DecimalHexNibble)
    {
        if (text.size() > 1 && !parseUnsignedComponent(text.left(text.size() - 1), 10,
                                                     &(*coordinates)[0]))
        {
            return false;
        }
        return parseUnsignedComponent(text.right(1), 16, &(*coordinates)[1]);
    }
    if (rule.grammar == PlcNativeGrammar::LgLength)
    {
        if (text.size() == 1)
        {
            return parseUnsignedComponent(text, 16, &(*coordinates)[1]);
        }
        return parseUnsignedComponent(text, 10, &(*coordinates)[0]);
    }
    normalized = text;
    normalized.replace(QChar(u':'), QChar(u'.'));
    parts = normalized.split(QChar(u'.'), Qt::KeepEmptyParts);
    if (parts.size() != rule.componentCount)
    {
        return false;
    }
    // Delimiters carry bank/word/bit positions and cannot be freely interchanged.
    if (rule.grammar == PlcNativeGrammar::Integer &&
        (text.contains(QChar(u':')) || text.contains(QChar(u'.'))))
    {
        return false;
    }
    if (rule.grammar == PlcNativeGrammar::Bit && text.contains(QChar(u':')))
    {
        return false;
    }
    if (rule.grammar == PlcNativeGrammar::BankInteger &&
        (text.count(QChar(u':')) != 1 || text.contains(QChar(u'.'))))
    {
        return false;
    }
    if (rule.grammar == PlcNativeGrammar::BankBit &&
        (text.count(QChar(u':')) != 1 || text.count(QChar(u'.')) != 1 ||
         text.indexOf(QChar(u':')) > text.indexOf(QChar(u'.'))))
    {
        return false;
    }
    if ((rule.grammar == PlcNativeGrammar::Bit || rule.grammar == PlcNativeGrammar::BankBit) &&
        rule.minorWidth > 1 && parts.last().size() != rule.minorWidth)
    {
        return false;
    }
    for (index = 0; index < rule.componentCount; ++index)
    {
        radix = rule.majorRadix;
        if ((rule.grammar == PlcNativeGrammar::BankInteger ||
             rule.grammar == PlcNativeGrammar::BankBit) && index == 0)
        {
            radix = 10;
        }
        if ((rule.grammar == PlcNativeGrammar::Bit || rule.grammar == PlcNativeGrammar::BankBit) &&
            index == rule.componentCount - 1)
        {
            radix = rule.minorRadix;
        }
        if (!parseUnsignedComponent(parts[index], radix, &(*coordinates)[index]))
        {
            return false;
        }
    }
    return true;
}

/******************************************************************************
 * Function Name   : formatCoordinates
 * Description     : Produce a stable spelling while preserving meaningful leading zeros.
 * Input Parameters: rule, coordinates
 * Return Value    : Canonical text for already validated components.
 * Date            : 2026.11.09
 ******************************************************************************/
QString formatCoordinates(const PlcNativeFamilyRule &rule,
                           const std::array<u32, 3> &coordinates) //20261109-0 add
{
    QStringList parts;
    QString prefix;
    int index;
    int radix;

    if (rule.grammar == PlcNativeGrammar::PackedDecimalBit)
    {
        return QString::number(static_cast<quint64>(coordinates[0]) * 100 + coordinates[1]);
    }
    if (rule.grammar == PlcNativeGrammar::DecimalHexNibble)
    {
        prefix = coordinates[0] == 0 ? QString() : QString::number(coordinates[0]);
        return prefix + QString::number(coordinates[1], 16).toUpper();
    }
    if (rule.grammar == PlcNativeGrammar::LgLength)
    {
        if (coordinates[0] == 0)
        {
            return QString::number(coordinates[1], 16).toUpper();
        }
        return QString::number(coordinates[0]).rightJustified(2, QChar(u'0'));
    }
    for (index = 0; index < rule.componentCount; ++index)
    {
        radix = rule.majorRadix;
        if ((rule.grammar == PlcNativeGrammar::BankInteger ||
             rule.grammar == PlcNativeGrammar::BankBit) && index == 0)
        {
            radix = 10;
        }
        if ((rule.grammar == PlcNativeGrammar::Bit || rule.grammar == PlcNativeGrammar::BankBit) &&
            index == rule.componentCount - 1)
        {
            radix = rule.minorRadix;
        }
        parts.append(QString::number(coordinates[index], radix).toUpper());
    }
    if (rule.grammar == PlcNativeGrammar::Bit || rule.grammar == PlcNativeGrammar::BankBit)
    {
        parts.last() = parts.last().rightJustified(rule.minorWidth, QChar(u'0'));
    }
    if (rule.grammar == PlcNativeGrammar::Integer)
    {
        return parts[0];
    }
    if (rule.grammar == PlcNativeGrammar::Bit)
    {
        return parts[0] + QChar(u'.') + parts[1];
    }
    if (rule.grammar == PlcNativeGrammar::BankInteger)
    {
        return parts[0] + QChar(u':') + parts[1];
    }
    return parts[0] + QChar(u':') + parts[1] + QChar(u'.') + parts[2];
}

