/******************************************************************************
 * Function Name   : plcNativeFamilyRule
 * Description     : Bind recovered rules to original catalog content and reject unknown revisions.
 * Input Parameters: profile, family, rule, error
 * Return Value    : True with an immutable rule copy.
 * Date            : 2026.11.09
 ******************************************************************************/
bool plcNativeFamilyRule(const PlcProfile &profile, const QString &family,
                         PlcNativeFamilyRule *rule, QString *error) //20261109-0 add
{
    const StoredProfile *binding;
    const StoredRule *stored;
    PlcNativeFamilyRule candidate;
    bool familyDeclared;
    int index;

    binding = nullptr;
    stored = nullptr;
    familyDeclared = false;
    for (const StoredProfile &entry : storedProfiles)
    {
        if (profile.id == QString::fromLatin1(entry.id))
        {
            binding = &entry;
            break;
        }
    }
    if (binding == nullptr || profile.sourceSha256 != QString::fromLatin1(binding->sha256))
    {
        return failNative(error, QStringLiteral("PLC 配置与已验证的原生地址目录版本不一致。"));
    }
    for (const PlcFamily &declared : profile.families)
    {
        if (declared.name == family)
        {
            familyDeclared = true;
            break;
        }
    }
    if (!familyDeclared)
    {
        return failNative(error, QStringLiteral("此版本的 PLC 配置未声明所选地址族。"));
    }
    for (const StoredRule &entry : storedRules)
    {
        if (entry.model == binding->model && family == QString::fromLatin1(entry.family))
        {
            stored = &entry;
            break;
        }
    }
    if (stored == nullptr)
    {
        return failNative(error, QStringLiteral("此 PLC 地址族的原生类型或数字格式尚未验证。"));
    }
    candidate.profileId = profile.id;
    candidate.family = family;
    candidate.evidence = QStringLiteral("Common.dll V5.1 SHA256 1ec540ff8fe1a070dd32fd597d8c447f645dcbdff829d6aa474aec4b3c0e3429; static dispatch and isolated x86 pure-function oracle; numeric VA ") + QString::fromLatin1(stored->numericFunction);
    candidate.grammar = stored->grammar;
    candidate.typeByte = stored->typeByte;
    candidate.ordinal = stored->ordinal;
    candidate.componentCount = stored->componentCount;
    candidate.majorRadix = stored->majorRadix;
    candidate.minorRadix = stored->minorRadix;
    candidate.minorWidth = stored->minorWidth;
    candidate.exactCountBoundary = stored->exactCountBoundary;
    candidate.hasExcludedNumericRange = stored->hasExcludedNumericRange;
    candidate.excludedNumericMinimum = stored->excludedNumericMinimum;
    candidate.excludedNumericMaximum = stored->excludedNumericMaximum;
    for (index = 0; index < 3; ++index)
    {
        candidate.minimum[index] = stored->minimum[index];
        candidate.maximum[index] = stored->maximum[index];
    }
    for (index = 0; index < 4; ++index)
    {
        candidate.numericTerms[index] = stored->numericTerms[index];
        candidate.countTerms[index] = stored->countTerms[index];
    }
    if (rule != nullptr)
    {
        *rule = candidate;
    }
    if (error != nullptr)
    {
        error->clear();
    }
    return true;
}

/******************************************************************************
 * Function Name   : parseNativePlcAddress
 * Description     : Validate strict syntax, coordinate domains and explicitly observed N constraints.
 * Input Parameters: profile, family, value, transferCount, address, error
 * Return Value    : True with canonical native numeric fields; no transport is accessed.
 * Date            : 2026.11.09
 ******************************************************************************/
bool parseNativePlcAddress(const PlcProfile &profile, const QString &family,
                           const QString &value, u32 transferCount,
                           PlcNativeParsedAddress *address, QString *error) //20261109-0 add
{
    PlcNativeFamilyRule rule;
    PlcNativeParsedAddress candidate;
    std::array<u32, 3> coordinates;
    qint64 numeric;
    qint64 maximumCount;
    int index;

    if (!plcNativeFamilyRule(profile, family, &rule, error))
    {
        return false;
    }
    if (transferCount == 0)
    {
        return failNative(error, QStringLiteral("地址访问数量 N 必须大于零。"));
    }
    if (!parseCoordinates(rule, value, &coordinates))
    {
        return failNative(error, QStringLiteral("地址不符合所选 PLC 地址族的原生数字格式。"));
    }
    numeric = rule.numericTerms[0];
    maximumCount = rule.countTerms[0];
    for (index = 0; index < rule.componentCount; ++index)
    {
        if (coordinates[index] < rule.minimum[index] || coordinates[index] > rule.maximum[index])
        {
            return failNative(error, QStringLiteral("地址分量超出已验证的原生范围。"));
        }
        numeric += rule.numericTerms[index + 1] * coordinates[index];
        maximumCount += rule.countTerms[index + 1] * coordinates[index];
    }
    if (numeric < 0 || numeric > std::numeric_limits<u32>::max() || maximumCount < 1 ||
        maximumCount > std::numeric_limits<u32>::max() || transferCount > maximumCount)
    {
        return failNative(error, QStringLiteral("地址与访问数量 N 的组合超出已验证的原生范围。"));
    }
    if (rule.hasExcludedNumericRange && numeric >= rule.excludedNumericMinimum &&
        numeric <= rule.excludedNumericMaximum)
    {
        return failNative(error, QStringLiteral("此地址位于 PLC 不允许访问的地址区间。"));
    }
    candidate.canonicalValue = formatCoordinates(rule, coordinates);
    candidate.typeByte = rule.typeByte;
    candidate.ordinal = rule.ordinal;
    candidate.numeric = static_cast<u32>(numeric);
    candidate.maximumCount = static_cast<u32>(maximumCount);
    candidate.exactCountBoundary = rule.exactCountBoundary;
    if (address != nullptr)
    {
        *address = candidate;
    }
    if (error != nullptr)
    {
        error->clear();
    }
    return true;
}

/******************************************************************************
 * Function Name   : plcNativeInitialAddressValue
 * Description     : Validate formatted component minima before exposing an initial editor value.
 * Input Parameters: profile, family, value, error
 * Return Value    : True with a valid N-one value; caller text survives every failure.
 * Date            : 2026.11.09
 ******************************************************************************/
bool plcNativeInitialAddressValue(const PlcProfile &profile, const QString &family,
                                  QString *value, QString *error) //20261109-0 add
{
    PlcNativeFamilyRule rule;
    PlcNativeParsedAddress parsed;
    QString initial;

    if (!plcNativeFamilyRule(profile, family, &rule, error))
    {
        return false;
    }
    initial = formatCoordinates(rule, rule.minimum);
    if (!parseNativePlcAddress(profile, family, initial, 1, &parsed, error))
    {
        return false;
    }
    if (value != nullptr)
    {
        *value = parsed.canonicalValue;
    }
    return true;
}
